                        <button className="w-full mt-2 py-2.5 rounded-[10px] text-[13px] cursor-pointer border border-[#ef4444] text-[#ef4444] bg-transparent" style={{ fontWeight: 600 }} onClick={() => deletePlannerBlock(block.id)}>
