}

interface ModalState {
  open: boolean;
  title: string;
  content: React.ReactNode;
  onBack?: (() => void) | null;
}

interface ChatState {
  open: boolean;
  id: string | null;
  type: 'agent' | 'personnel' | 'eu' | 'customer' | 'group' | 'contact' | null;
  topicId: number | null;
  topicsOpen: boolean;
