      initial={window.innerWidth >= 768 ? { x: '-100%', opacity: 0.5 } : { y: '100%' }}
      animate={window.innerWidth >= 768 ? { x: 0, opacity: 1 } : { y: 0 }}
      exit={window.innerWidth >= 768 ? { x: '-100%' } : { y: '100%' }}
      transition={{ duration: 0.32, ease: [0.32, 0.72, 0, 1] }}
