            style={{ background: 'var(--aw-bg-card)', backdropFilter: 'blur(14px)', WebkitBackdropFilter: 'blur(14px)', borderLeft: '1px solid var(--aw-border)', boxShadow: '-8px 0 32px rgba(0,0,0,0.3)' }}
