              background: m.sent
                ? 'linear-gradient(135deg, #7b62fc, #5c4abd)'
                : 'var(--aw-chat-recv, rgba(255,255,255,0.7))',
              color: m.sent ? '#fff' : 'var(--aw-text-primary)',
              lineHeight: 1.6,
              boxShadow: m.sent
