  customerPhone?: string;
  issueDate: string;     // Persian date string
  dueDate: string;
  lines: InvoiceLine[];
  taxPct: number;        // %
  discount: number;      // rial
  status: 'paid' | 'pending' | 'overdue' | 'draft';
