            boxShadow: chatListTab === 'interactions' ? 'inset 0 1px 1px rgba(255,255,255,0.35)' : 'none',
            color: chatListTab === 'interactions' ? 'color-mix(in srgb, var(--aw-eu-primary) 82%, black)' : 'var(--aw-text-secondary)',
