      </div>
    </div>
  );
}

function OrderDetail({ order: o }: { order: Order }) {
  const { closeModal, openChat, orders, setOrders, showToast } = useApp();

  const cancelOrder = () => {
    setOrders(prev => prev.map(or => or.id === o.id ? { ...or, status: 'cancelled' as const } : or));
