              )}
            </AnimatePresence>

            <div className="mb-2.5">
              <div className="text-[10px] text-[var(--aw-text-muted)] mb-1.5 px-0.5" style={{ fontWeight: 600 }}>زمان‌بندی</div>
              <div className="flex gap-1.5 flex-wrap">
