                    }`}
                    style={newDate === d.value && !showCalendar ? { background: '#6366f1', fontWeight: 600 } : { fontWeight: 500 }}
                    onClick={() => { setNewDate(d.value); setShowCalendar(false); setSelectedCalDate(null); }}
