  { id: 'order', label: 'سفارشات',   icon: 'fa-solid fa-bag-shopping',  color: '#F59E0B' },
  { id: 'plan',  label: 'برنامه‌ها', icon: 'fa-solid fa-calendar-days', color: '#3B82F6' },
