                      </div>
                    )}
                  </div>
                )}
              </div>
            </motion.div>
          );
        })}
        {filtered.length === 0 && <EmptyState icon="fa-solid fa-th-large" text="محصولی یافت نشد" />}
      </div>
    </div>
  );
}

