const SEGMENT_TABS = [
  { id: 'segments', label: 'سگمنت‌ها', icon: 'fa-solid fa-layer-group' },
  { id: 'personas', label: 'پرسوناها', icon: 'fa-solid fa-user-tag' },
  { id: 'targets', label: 'هدف‌گذاری', icon: 'fa-solid fa-bullseye' },
