                ))}
              </div>
            )}
          </FormGroup>
        </>
      ) : (
        <>
          <FormGroup label="پلتفرم جلسه">
            <div className="grid grid-cols-5 gap-1.5">
              {(Object.keys(platformConfig) as (keyof typeof platformConfig)[]).map(p => {
                const c = platformConfig[p];
                const active = platform === p;
                return (
                  <button
                    key={p}
