          { key: 'followup', label: 'ایجاد خودکار تسک‌های پیگیری', desc: 'تصمیمات جلسه به تسک تبدیل و به افراد مسئول ارجاع شود', value: createFollowupTasks, setter: setCreateFollowupTasks, icon: 'fa-solid fa-list-check' },
        ].map(opt => (
