      {/* Funnel Visual */}
      <div className="flex-1 overflow-y-auto px-4 pb-4 aw-scroll">
        <motion.div variants={staggerContainer} initial="initial" animate="animate">
          {FUNNEL_STAGES.map((stage, idx) => (
