                            <div className="text-[10px] text-[var(--aw-text-muted)]">{it.qty.toLocaleString('fa-IR')} × {formatPrice(it.price)}</div>
                          </div>
                          <span className="text-[12px]" style={{ color: '#10B981', fontWeight: 700 }}>{formatPrice(it.qty * it.price)}</span>
