      </div>

      {/* Period selector */}
      <div className="flex gap-1 p-1 mx-4 mt-3 mb-2 overflow-x-auto aw-noscroll" style={tabBarStyle}>
        {(['today', 'week', 'month', 'custom'] as const).map(p => (
