                  <span className="text-[12px] text-[var(--aw-text-secondary)]">{item.img} {item.name}</span>
                  <span className="text-[12px]" style={{ color: item.stock === 0 ? '#EF4444' : '#F59E0B', fontWeight: 700 }}>
                    {item.stock === 0 ? 'ناموجود' : `${item.stock} ${item.unit}`}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

