  const snoozeReminder = (id: number, label: string) => {
    setReminders(prev => prev.map(r => r.id === id ? { ...r, when: `${label} ⏰`, snoozed: true } as any : r));
    setSnoozeId(null);
    showToast(`یادآوری به ${label} موکول شد`);
  };
  const [calYear, setCalYear] = useState(1404);
