  const confirm = () => {
    if (amountNum <= 0) { showToast('مبلغ معتبر وارد کنید', 'error'); return; }
    showToast(mode === 'in' ? 'دریافت ثبت شد ✅' : 'پرداخت ثبت شد ✅', 'success');
    setAmount(''); setMode(null); setTab('history');
