              <div className="text-[10px] text-[var(--aw-text-muted)]">{toFa(String(TX.length))} تراکنش این هفته</div>
            </div>
            <div className="text-[14px]" style={{ fontWeight: 800, color: 'var(--aw-primary)', direction: 'ltr' }}>{fmt(totalIn - totalOut)}</div>
